import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { spawnSync } from 'node:child_process';
import { fileURLToPath, pathToFileURL } from 'node:url';
import { CATEGORIES } from '../config/categories.js';

/**
 * Builds verified question files.
 *
 *   node src/scripts/buildQuestions.js [topic-substring ...]
 *
 * Reads  src/data/questions/src/NN-<topic>.js   (authored questions with a reference C `solution`)
 * Writes src/data/questions/built/NN-<topic>.json (expected outputs generated by RUNNING the solution)
 *
 * Expected outputs are never typed by hand: they come from compiling and executing the reference
 * solution on every test input. Each run is repeated to reject non-deterministic solutions.
 */
const here = path.dirname(fileURLToPath(import.meta.url));
const SRC_DIR = path.join(here, '../data/questions/src');
const OUT_DIR = path.join(here, '../data/questions/built');

export const DEFAULT_STARTER = `#include <stdio.h>

int main() {
    // Write your code here

    return 0;
}
`;

const DIFFICULTY_PLAN = { Easy: 10, Medium: 7, Hard: 3 };
const RUN_TIMEOUT_MS = 5000;

function fail(file, slug, message) {
  throw new Error(`[${file}] ${slug ? `${slug}: ` : ''}${message}`);
}

function validateShape(file, topic, questions) {
  if (!Array.isArray(questions) || questions.length !== 20) {
    fail(file, '', `expected exactly 20 questions, found ${questions?.length}`);
  }
  const counts = { Easy: 0, Medium: 0, Hard: 0 };
  const order = ['Easy', 'Medium', 'Hard'];
  let lastRank = 0;
  const slugs = new Set();

  questions.forEach((q, i) => {
    for (const key of ['slug', 'title', 'difficulty', 'description', 'solution']) {
      if (typeof q[key] !== 'string' || !q[key].trim()) fail(file, q.slug, `missing "${key}"`);
    }
    if (!/^[a-z0-9]+(-[a-z0-9]+)*$/.test(q.slug)) fail(file, q.slug, 'slug must be kebab-case');
    if (slugs.has(q.slug)) fail(file, q.slug, 'duplicate slug in topic');
    slugs.add(q.slug);
    if (!(q.difficulty in counts)) fail(file, q.slug, `bad difficulty ${q.difficulty}`);
    counts[q.difficulty] += 1;
    const rank = order.indexOf(q.difficulty);
    if (rank < lastRank) fail(file, q.slug, `question ${i + 1}: difficulty must not decrease (Easy -> Medium -> Hard)`);
    lastRank = rank;
    if (!Array.isArray(q.constraints) || q.constraints.length === 0) fail(file, q.slug, 'constraints[] required');
    if (!Array.isArray(q.tests) || q.tests.length < 4) fail(file, q.slug, 'need at least 4 tests');
    if (q.tests[0].hidden) fail(file, q.slug, 'first test is used as the example and must not be hidden');
    if (q.tests.filter((t) => !t.hidden).length < 2) fail(file, q.slug, 'need at least 2 sample (non-hidden) tests');
    if (q.tests.filter((t) => t.hidden).length < 2) fail(file, q.slug, 'need at least 2 hidden tests');
    q.tests.forEach((t) => {
      if (typeof t.input !== 'string') fail(file, q.slug, 'every test needs a string "input" (use "" for none)');
    });
  });

  for (const [level, expected] of Object.entries(DIFFICULTY_PLAN)) {
    if (counts[level] !== expected) fail(file, '', `expected ${expected} ${level}, found ${counts[level]}`);
  }
}

function compile(code, dir) {
  fs.writeFileSync(path.join(dir, 'main.c'), code);
  const r = spawnSync(
    'cc',
    ['-std=c11', '-Wall', '-Wno-unused-result', '-O1', '-o', 'main', 'main.c', '-lm'],
    { cwd: dir, encoding: 'utf8', timeout: 20000 },
  );
  return { ok: r.status === 0, output: `${r.stdout}${r.stderr}`.trim() };
}

// Every run gets a fresh directory so file-handling solutions never see leftovers.
function runOnce(binary, input) {
  const cwd = fs.mkdtempSync(path.join(os.tmpdir(), 'vv-run-'));
  try {
    const r = spawnSync(binary, [], {
      cwd,
      input,
      encoding: 'utf8',
      timeout: RUN_TIMEOUT_MS,
      maxBuffer: 1024 * 1024,
    });
    return { code: r.status, signal: r.signal, stdout: r.stdout ?? '', stderr: r.stderr ?? '' };
  } finally {
    fs.rmSync(cwd, { recursive: true, force: true });
  }
}

function buildQuestion(file, topic, q, index) {
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'vv-build-'));
  try {
    const compiled = compile(q.solution, dir);
    if (!compiled.ok) fail(file, q.slug, `reference solution does not compile:\n${compiled.output}`);
    if (compiled.output) console.warn(`  warning in ${q.slug}:\n${compiled.output}`);

    const binary = path.join(dir, 'main');
    const testCases = q.tests.map((t, i) => {
      const input = t.input;
      const a = runOnce(binary, input);
      if (a.code !== 0) fail(file, q.slug, `test ${i + 1} exited with ${a.code ?? a.signal}: ${a.stderr.slice(0, 200)}`);
      const expectedOutput = a.stdout.replace(/\s+$/, '');
      if (!expectedOutput) fail(file, q.slug, `test ${i + 1} produced no output`);
      if (runOnce(binary, input).stdout.replace(/\s+$/, '') !== expectedOutput) {
        fail(file, q.slug, `test ${i + 1} is not deterministic`);
      }
      return { input, expectedOutput, isHidden: Boolean(t.hidden) };
    });

    return {
      slug: q.slug,
      title: q.title,
      category: topic.slug,
      difficulty: q.difficulty,
      description: q.description,
      hint: q.hint || '',
      ...(topic.slug === 'basics'
        ? { solution: q.solution, solutionNotes: q.solutionNotes || '' }
        : {}),
      exampleInput: testCases[0].input,
      exampleOutput: testCases[0].expectedOutput,
      constraints: q.constraints,
      starterCode: q.starterCode || DEFAULT_STARTER,
      testCases,
      topicOrder: topic.order,
      questionOrder: index + 1,
    };
  } finally {
    fs.rmSync(dir, { recursive: true, force: true });
  }
}

async function main() {
  const filters = process.argv.slice(2);
  const files = fs
    .readdirSync(SRC_DIR)
    .filter((f) => /^\d\d-.+\.js$/.test(f))
    .filter((f) => filters.length === 0 || filters.some((x) => f.includes(x)))
    .sort();

  if (files.length === 0) throw new Error('No question source files matched');
  fs.mkdirSync(OUT_DIR, { recursive: true });

  for (const file of files) {
    const slug = file.replace(/^\d\d-/, '').replace(/\.js$/, '');
    const topic = CATEGORIES.find((c) => c.slug === slug);
    if (!topic) fail(file, '', `unknown topic "${slug}" (see config/categories.js)`);
    if (topic.order !== Number(file.slice(0, 2))) fail(file, '', `file prefix must be ${String(topic.order).padStart(2, '0')}`);

    const questions = (await import(pathToFileURL(path.join(SRC_DIR, file)).href)).default;
    validateShape(file, topic, questions);

    const built = questions.map((q, i) => buildQuestion(file, topic, q, i));
    fs.writeFileSync(path.join(OUT_DIR, file.replace(/\.js$/, '.json')), `${JSON.stringify(built, null, 2)}\n`);
    console.log(`OK  ${file}: ${built.length} questions, ${built.reduce((n, q) => n + q.testCases.length, 0)} test cases`);
  }
}

main().catch((err) => {
  console.error(`\nBUILD FAILED\n${err.message}`);
  process.exit(1);
});
